styles:
.b-showcase-numbers {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-numbers__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-numbers__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-numbers--narrow .b-showcase-numbers__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

.b-showcase-numbers__list {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-showcase-numbers__number {
    font-size: var(--site-font-size-2);
    font-weight: 700;
}
